/**
 * Removes Nunjucks-style template expressions from a single string.
 *
 * Handles both variable syntax (`{{ ... }}`) and block-tag syntax (`{% ... %}`),
 * scanning left-to-right so that whichever delimiter opens first "owns" the
 * region up to its matching close. This is what makes interleaving safe: a
 * `{% %}` nested inside `{{ }}` (or vice-versa) is consumed as part of the
 * outer expression rather than surviving as a re-formed, injectable tag.
 *
 * An opening delimiter with no matching close of its own type is left intact
 * (scanning continues past it so any later, well-formed expressions are still
 * stripped). Text surrounding a stripped expression is preserved verbatim.
 */
function stripTemplates(input: string): string {
  let result = '';
  let cursor = 0;

  while (cursor < input.length) {
    const varOpen = input.indexOf('{{', cursor);
    const tagOpen = input.indexOf('{%', cursor);

    // No more opening delimiters — append the remainder and finish.
    if (varOpen === -1 && tagOpen === -1) {
      result += input.slice(cursor);
      break;
    }

    // Pick whichever delimiter opens first.
    let openIdx: number;
    let closeToken: string;
    if (tagOpen === -1 || (varOpen !== -1 && varOpen < tagOpen)) {
      openIdx = varOpen;
      closeToken = '}}';
    } else {
      openIdx = tagOpen;
      closeToken = '%}';
    }

    const closeIdx = input.indexOf(closeToken, openIdx + 2);
    if (closeIdx === -1) {
      // Unpaired opener: keep it (and the text before it) intact, then keep
      // scanning past it for other, well-formed expressions.
      result += input.slice(cursor, openIdx + 2);
      cursor = openIdx + 2;
      continue;
    }

    // Well-formed expression: keep the text before it, drop the expression.
    result += input.slice(cursor, openIdx);
    cursor = closeIdx + closeToken.length;
  }

  return result;
}

/**
 * Returns a copy of a Konnect route with all Nunjucks-style template
 * expressions removed from its string fields, preventing template injection
 * when route data is rendered inside Insomnia.
 *
 * - `name` / `expression`: expressions stripped, surrounding text kept.
 * - `paths` / `hosts`: expressions stripped from each entry, surrounding text
 *   kept (entries are never dropped, even if they become empty).
 * - `methods`: entries stripped; entries that become empty are removed. If no
 *   entries remain the field becomes `null`.
 * - `headers`: values stripped; empty values are removed and a header whose
 *   value list (or whose stripped key) becomes empty is dropped entirely.
 *
 * `null` fields are passed through as `null`.
 */
export function sanitizeRoute(route: KonnectRoute): KonnectRoute {
  const name = route.name === null ? null : stripTemplates(route.name);
  const expression = route.expression === null ? null : stripTemplates(route.expression);
  const paths = route.paths === null ? null : route.paths.map(stripTemplates);
  const hosts = route.hosts === null ? null : route.hosts.map(stripTemplates);

  let methods: string[] | null = null;
  if (route.methods !== null) {
    const cleaned = route.methods.map(stripTemplates).filter(m => m !== '');
    methods = cleaned.length > 0 ? cleaned : null;
  }

  let headers: Record<string, string[]> | null = null;
  if (route.headers !== null) {
    const cleaned: Record<string, string[]> = {};
    for (const [key, values] of Object.entries(route.headers)) {
      const cleanKey = stripTemplates(key);
      if (cleanKey === '') { continue; }
      const cleanValues = values.map(stripTemplates).filter(v => v !== '');
      if (cleanValues.length === 0) { continue; }
      cleaned[cleanKey] = cleanValues;
    }
    headers = cleaned;
  }

  return {
    ...route,
    name,
    methods,
    paths,
    hosts,
    headers,
    expression,
  };
